import META from '../assets/pets/dawnlion/pet-meta-v1.json' with {type:'json'};
import {drawFrameBlend} from './fx-animation.mjs';
const folder='assets/pets/dawnlion/';
function cropStyle(file,rect){const size=file.includes('portraits')?[1774,887]:[1254,1254],[x,y,w,h]=rect;return `background-image:url('${folder+file}');background-size:${size[0]/w*100}% ${size[1]/h*100}%;background-position:${x/Math.max(1,size[0]-w)*100}% ${y/Math.max(1,size[1]-h)*100}%;aspect-ratio:${w}/${h}`;}
export function dawnPortraitStyle(form=0){const f=META.portraits[Math.max(0,Math.min(2,form))];return cropStyle(f.file,f.faceRect);}
export function dawnSkillStyle(index){const f=META.skills[['claw','ring','flame'][index]].icon;return cropStyle(f.file,f.rect);}
export async function loadDawnlionArt(art,progress=()=>{}){const files=[...new Set([...Object.values(META.motion).map(v=>v.file),META.uiAtlas.file,...Object.values(META.skills).map(v=>v.fx.file)])];art.dawnlion={meta:META,images:{}};await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{art.dawnlion.images[file]=image;progress();resolve();};image.onerror=()=>reject(Error('镇曜灵猊素材载入失败'));image.src=folder+file;})));}
export function drawDawnlion(c,w,e,art,alpha=1){const a=art.dawnlion;if(!a)return false;const m=META.motion[e.form||0],image=a.images[m.file],x=e.prevX+(e.x-e.prevX)*alpha,y=e.prevY+(e.y-e.prevY)*alpha,walking=e.state==='walk',phase=((e.walkPhase??e.cycle*40/130)*6)%6,frame=e.hp<=0?(w.time-(e.diedAt??w.time)<.3?14:15):e.hit>0?12:e.attackAt?7:e.attackPoseUntil>w.time?(e.pendingSkill===2?11:e.pendingSkill===1?10:8):e.recoverUntil>w.time?9:6;
 const draw=(index,opacity)=>{const f=m.frames[index],r=f.rect,s=f.spriteRect||r,scale=m.naturalHeight/m.referenceSourceHeight;c.save();c.globalAlpha*=opacity;c.drawImage(image,...s,(s[0]-r[0]-f.pivot[0])*scale,(s[1]-r[1]-f.pivot[1])*scale,s[2]*scale,s[3]*scale);c.restore();};
 c.save();c.translate(x,y);c.scale(e.face||1,1);if(walking&&frame===6&&e.hp>0){draw(Math.floor(phase),1-phase%1);draw((Math.floor(phase)+1)%6,phase%1);}else draw(frame,1);c.restore();return true;}
export function drawDawnSkill(c,w,f,e,art){const a=art.dawnlion;if(!a)return;const key=['claw','ring','flame'][e.index],m=META.skills[key].fx,image=a.images[m.file],t=Math.max(0,Math.min(1,(w.time-e.born)/e.duration)),value=t*3,i=Math.floor(value),frames=m.frames;
 c.save();c.translate(e.x,e.y);if(key==='claw')c.scale(f.face||1,1);drawFrameBlend(c,image,frames,{a:i,b:Math.min(3,i+1),mix:value-i},0,0,e.size||200,{reference:m.referenceSourceSize?.[0]||362,ground:!!m.grounded,alpha:Math.min(1,t*10,(1-t)*5)});c.restore();}
